CREATE TABLE IF NOT EXISTS quicksdk_product_sources (
  id TEXT PRIMARY KEY,
  game_name VARCHAR(255) NOT NULL,
  product_code VARCHAR(64) NOT NULL UNIQUE,
  source_file VARCHAR(255),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS ix_quicksdk_product_sources_game_name
  ON quicksdk_product_sources (game_name);

CREATE UNIQUE INDEX IF NOT EXISTS ix_quicksdk_product_sources_product_code
  ON quicksdk_product_sources (product_code);

ON CONFLICT (product_code) DO UPDATE SET
  game_name = EXCLUDED.game_name,
  source_file = EXCLUDED.source_file,
  updated_at = NOW();
